//! The colors of the window: egui's visuals, light and dark, made only from the palette of
//! takt's icon ([`crate::palette`], generated by the app icons tool of the vault). Shapes,
//! spacing and fonts stay egui's; only the colors come from here.

use egui::{Color32, Stroke, Theme, Visuals};

use crate::palette::{DARK, LIGHT, Palette};

/// A color of the palette for egui.
fn color([r, g, b]: [u8; 3]) -> Color32 {
    Color32::from_rgb(r, g, b)
}

/// The visuals of one mode.
#[must_use]
pub fn visuals(p: &Palette, dark: bool) -> Visuals {
    let mut v = if dark {
        Visuals::dark()
    } else {
        Visuals::light()
    };
    let (bg, surface, surface_2) = (color(p.bg), color(p.surface), color(p.surface_2));
    let (text, muted, line) = (color(p.text), color(p.muted), color(p.line));
    let (accent, hover) = (color(p.accent), color(p.accent_hover));
    v.panel_fill = bg;
    v.window_fill = surface;
    v.window_stroke = Stroke::new(1.0_f32, line);
    v.extreme_bg_color = surface;
    v.faint_bg_color = surface_2;
    v.code_bg_color = surface_2;
    v.hyperlink_color = accent;
    v.warn_fg_color = color(p.warn);
    v.error_fg_color = color(p.bad);
    v.selection.bg_fill = accent;
    v.selection.stroke = Stroke::new(1.0_f32, color(p.accent_text));
    let w = &mut v.widgets;
    w.noninteractive.bg_fill = bg;
    w.noninteractive.weak_bg_fill = bg;
    w.noninteractive.bg_stroke = Stroke::new(1.0_f32, line);
    w.noninteractive.fg_stroke = Stroke::new(1.0_f32, text);
    for state in [&mut w.inactive, &mut w.open] {
        state.bg_fill = surface_2;
        state.weak_bg_fill = surface_2;
        state.bg_stroke = Stroke::new(1.0_f32, line);
        state.fg_stroke = Stroke::new(1.0_f32, text);
    }
    w.hovered.bg_fill = surface_2;
    w.hovered.weak_bg_fill = surface_2;
    w.hovered.bg_stroke = Stroke::new(1.0_f32, hover);
    w.hovered.fg_stroke = Stroke::new(1.5_f32, text);
    w.active.bg_fill = accent;
    w.active.weak_bg_fill = accent;
    w.active.bg_stroke = Stroke::new(1.0_f32, hover);
    w.active.fg_stroke = Stroke::new(2.0_f32, color(p.accent_text));
    // Muted text (hints, the second line of the overlay) as egui's weak text.
    v.weak_text_color = Some(muted);
    v
}

/// Puts both modes into `ctx`; egui follows the system's choice between them.
pub fn install(ctx: &egui::Context) {
    ctx.set_visuals_of(Theme::Light, visuals(&LIGHT, false));
    ctx.set_visuals_of(Theme::Dark, visuals(&DARK, true));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_color_of_the_window_comes_from_the_palette() {
        for (p, dark) in [(&LIGHT, false), (&DARK, true)] {
            let v = visuals(p, dark);
            assert_eq!(v.dark_mode, dark);
            assert_eq!(v.panel_fill, color(p.bg));
            assert_eq!(v.window_fill, color(p.surface));
            assert_eq!(v.selection.bg_fill, color(p.accent));
            assert_eq!(v.hyperlink_color, color(p.accent));
            assert_eq!(v.widgets.inactive.fg_stroke.color, color(p.text));
            assert_eq!(v.widgets.active.bg_fill, color(p.accent));
            assert_eq!(v.error_fg_color, color(p.bad));
        }
    }
}
